head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDODS90002";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods90002.onpageload' });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {

};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_eClose_onclick
 * @description btn_eClose 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_eClose_onclick = function(e){
    try {
        scwin.e_close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods90002.btn_eClose_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_FileDown
 * @description File Down 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_FileDown = async function (action) {
    try { return await $c.data.downFile(action ?? "/sprtroom/fileDownload.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name setCookie
 * @description set Cookie 처리
 * @param {*} name name
 * @param {*} value value
 * @param {*} expiredays expiredays
 * @returns {void}
 * @hidden N
 */
scwin.setCookie = function (name, value, expiredays) { $c.util.setSessionStorage(name, value); };

/**
 * @method
 * @name e_close
 * @description e close 처리
 * @returns {void}
 * @hidden N
 */
scwin.e_close = function () {
    if ($("#ipt_todayNot").is(":checked")) {
        scwin.setCookie("JLDODS90002", "JLDODS90002", 1);
    }
    $c.win.closePopup();
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {*} filename filename
 * @param {*} realFilename realFilename
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (filename, realFilename) {
    $c.util.getComponent('dma_FileDownReq').set('method', 'popupFileDown');
    $c.util.getComponent('dma_FileDownReq').set('filename', filename);
    $c.util.getComponent('dma_FileDownReq').set('realFilename', realFilename);
    await scwin.tx_fn_FileDown('/sprtroom/fileDownload.do');
};
